                toggle names the option so it stays findable when collapsed. */}
            <div>
              <button
                type="button"
                onClick={() => setAdoptAdvancedOpen((open) => !open)}
                aria-expanded={adoptAdvancedOpen}
                aria-controls="adopt-project-advanced"
