207|  /***
208|   * MARK: handleSearchSelect
209|   * @description Jumps to a search result: switches to the entry's tab, then
210|   *   the highlight effect scrolls the target into view and rings it.
211|   *   Fail-safe: a malformed entry (unknown tab, missing element id) is
212|   *   ignored instead of switching tabs or highlighting nothing.
213|   ***/
214|  const handleSearchSelect = (entry) => {
215|    if (!entry || typeof entry !== 'object') return;
216|    if (
217|      !PROJECT_SETTINGS_SECTIONS.includes(entry.tab) ||
218|      typeof entry.elementId !== 'string' ||
219|      !entry.elementId
220|    ) {
221|      return;
222|    }
223|    // Only highlight when the switch actually happened: if the unsaved-edits
224|    // guard blocks it, the target is not on screen and ringing it (or a stale
225|    // element with the same id) would mislead.
226|    if (!handleSectionChange(entry.tab)) return;
227|    highlightSeqRef.current += 1;
228|    setHighlightTarget({ id: entry.elementId, at: highlightSeqRef.current });
229|  };
230|
231|  // Scrolls the search target into view and highlights it briefly. Guarded
232|  // for test DOMs without `scrollIntoView`, and no-ops when the target id
233|  // is not on the active tab (e.g. a conditional field). Cleanup removes the
234|  // ring from the previous target: without this, picking a second result
235|  // while the first ring is still showing would clear the first hide timer
236|  // and leave that ring stuck on forever.
237|  useEffect(() => {
238|    if (!highlightTarget) return undefined;
239|    const targetId = highlightTarget.id;
240|    const clearRing = () => {
241|      const el = typeof document !== 'undefined' ? document.getElementById(targetId) : null;
242|      el?.classList?.remove('ring-2', 'ring-primary', 'rounded-sm');
243|    };
244|    const showTimer = setTimeout(() => {
245|      const el = typeof document !== 'undefined' ? document.getElementById(targetId) : null;
246|      if (el) {
247|        if (typeof el.scrollIntoView === 'function') {
248|          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
249|        }
250|        el.classList.add('ring-2', 'ring-primary', 'rounded-sm');
251|      }
252|    }, HIGHLIGHT_SHOW_DELAY_MS);
253|    const hideTimer = setTimeout(clearRing, HIGHLIGHT_HIDE_DELAY_MS);
254|    return () => {
255|      clearTimeout(showTimer);
256|      clearTimeout(hideTimer);
257|      clearRing();
258|    };
259|  }, [highlightTarget, effectiveSection]);
