287|              className={`px-4 py-2 text-xs font-bold uppercase tracking-wider rounded-sm transition-all flex items-center gap-2 cursor-pointer ${
288|                effectiveSection === tab.id
289|                  ? 'bg-primary text-on-primary font-bold shadow-sm'
290|                  : 'bg-surface-container hover:bg-surface-container-high text-text-muted hover:text-on-surface'
291|              }`}
