86|/***
87| * MARK: pruneStaleTestDirectories
88| * @description Removes abandoned kainbain scratch directories from the
89| *   temporary folder if they are older than maximumAgeInMilliseconds
90| *   (default: 30 minutes). Vitest setups mint isolated roots per worker and
91| *   agents mint per-attempt deploy/stage/survey/recon dirs; on long-running
92| *   servers with memory-backed tmpfs, the tens of thousands of accumulated
93| *   roots otherwise exhaust inodes and eat gigabytes of RAM during CI
94| *   (2026-11-03: 49k entries, 4.1G/7.6G of tmpfs). One broad `kainbain-`
95| *   stem covers scratch families invented tomorrow; the keep-list below
96| *   protects the few names that must survive (compile caches, the canary
97| *   suite's live scratch roots).
98| * @example pruneStaleTestDirectories({ temporaryDirectoryPath: "/tmp", maximumAgeInMilliseconds: 1800000 })
99| * @param {Object} [options]
100| * @param {string} [options.temporaryDirectoryPath] - path to inspect, defaults to os.tmpdir().
101| * @param {number} [options.maximumAgeInMilliseconds] - cutoff age, defaults to 30 minutes.
102| * @returns {number} count of pruned directories
103| ***/
104|export function pruneStaleTestDirectories({
105|	temporaryDirectoryPath = os.tmpdir(),
106|	maximumAgeInMilliseconds = 30 * 60 * 1000,
107|} = {}) {
108|	let prunedDirectoryCount = 0;
109|	try {
110|		const directoryEntries = fs.readdirSync(temporaryDirectoryPath, { withFileTypes: true });
111|		const currentTimestamp = Date.now();
112|		const scratchDirectoryPrefixes = ["kainbain-", "kb-", "survey-", "sitedocs-"];
113|		// Never prune these: compile caches are big, shared, and harmless,
114|		// and kb-canary-e2e holds a possibly LIVE canary scratch stack from
115|		// a concurrent task (it reclaims itself after 24h in
116|		// canary-e2e/playwright.config.js).
117|		const keepDirectoryNames = new Set(["kb-canary-e2e"]);
118|
119|		for (const entry of directoryEntries) {
120|			if (!entry.isDirectory()) {
121|				continue;
122|			}
123|			const matchesScratchPrefix = scratchDirectoryPrefixes.some((prefix) =>
124|				entry.name.startsWith(prefix),
125|			);
126|			if (!matchesScratchPrefix) {
127|				continue;
128|			}
129|			if (keepDirectoryNames.has(entry.name) || entry.name.includes("cache")) {
130|				continue;
131|			}
132|			const entryFullPath = path.join(temporaryDirectoryPath, entry.name);
133|			try {
134|				const entryStatistics = fs.statSync(entryFullPath);
135|				const entryAgeInMilliseconds = currentTimestamp - entryStatistics.mtimeMs;
136|				if (entryAgeInMilliseconds > maximumAgeInMilliseconds) {
137|					fs.rmSync(entryFullPath, { recursive: true, force: true });
138|					prunedDirectoryCount += 1;
139|				}
140|			} catch {
141|				// Ignore permission errors or concurrent deletion races
142|			}
143|		}
144|	} catch {
145|		// Ignore readdir failures if temporary directory is unreadable
146|	}
147|	return prunedDirectoryCount;
148|}
