154|  // between menuitems, Escape closes and returns focus to the trigger.
155|  const handleMenuKeyDown = (e) => {
156|    const current = itemRefs.current.findIndex((el) => el === document.activeElement);
157|    if (e.key === 'Escape') {
158|      e.preventDefault();
159|      setIsOpen(false);
160|      triggerRef.current?.focus?.();
161|    } else if (e.key === 'ArrowDown') {
162|      e.preventDefault();
163|      focusItem(current + 1);
164|    } else if (e.key === 'ArrowUp') {
165|      e.preventDefault();
166|      focusItem(current - 1 < 0 ? itemRefs.current.length - 1 : current - 1);
167|    } else if (e.key === 'Home') {
168|      e.preventDefault();
169|      focusItem(0);
